<h2>MongoDB Integration</h2>
<p>Now your database is ready with username/password. Let's install the mongoose npm package on our local. <code>$ npm install mongoose</code></p>
<p>Note: To save your MongoDB details, you need to have a file with the name <code>.env</code>, which allows you to send these values in <code>process.env</code> or Node.js environment variables.</p>
<pre><code class="language-bash">MONGO_HOST=my_hostname
MONGO_PASS=my_password
MONGO_USER=my_username
MONGO_DB=my_db_name
</code></pre>
<blockquote>
<p>You will get above information in MongoDB connect option like <code>mongodb+srv://my_username:my_password@my_hostname/my_db_name?retryWrites=true&amp;w=majority</code></p>
</blockquote>
<p>After creating the <code>.env</code> file you need to install a couple of packages, please refer to the <code>package.json</code> file below:</p>
<pre><code class="language-json">{
  &quot;name&quot;: &quot;node&quot;,
  &quot;version&quot;: &quot;1.0.0&quot;,
  &quot;description&quot;: &quot;&quot;,
  &quot;main&quot;: &quot;app.js&quot;,
  &quot;scripts&quot;: {
    &quot;start&quot;: &quot;nodemon app.js&quot;
  },
  &quot;keywords&quot;: [],
  &quot;author&quot;: &quot;&quot;,
  &quot;license&quot;: &quot;ISC&quot;,
  &quot;dependencies&quot;: {
    &quot;body-parser&quot;: &quot;^1.19.0&quot;,
    &quot;dotenv&quot;: &quot;^10.0.0&quot;,
    &quot;ejs&quot;: &quot;^3.1.6&quot;,
    &quot;express&quot;: &quot;^4.17.1&quot;,
    &quot;mongoose&quot;: &quot;^5.13.5&quot;,
    &quot;nodemon&quot;: &quot;^2.0.12&quot;
  }
}
</code></pre>
<p>Now we are ready to change our <code>app.js</code> file with MongoDB changes.</p>
<p>First, you need to require the <code>dotenv</code> package to get MongoDB credentials from <code>.env</code> or <code>process.env</code>.</p>
<pre><code class="language-bash">require(&quot;dotenv&quot;).config()
</code></pre>
<p>After requiring the package you will get access to all environment variables like this: <code>const { MONGO_USER, MONGO_HOST, MONGO_PASS, MONGO_DB } = process.env;</code></p>
<p>Now we will connect the application with MongoDB, it requires the below steps:</p>
<pre><code class="language-js">require('dotenv').config();
const mongoose = require('mongoose');

// connect to the database
async function connectDB() {
  const {MONGO_USER, MONGO_HOST, MONGO_PASS, MONGO_DB} = process.env;
  await mongoose.connect(
    `mongodb+srv://${MONGO_USER}:${MONGO_PASS}@${MONGO_HOST}/${MONGO_DB}`,
    {
      useNewUrlParser: true,
      useUnifiedTopology: true,
      useFindAndModify: false,
      useCreateIndex: true
    }
  );
}

connectDB();
</code></pre>
<p>We need to require the <code>mongoose</code> package, and then followed by <code>mongoose.connect()</code> we will connect our current to our MongoDB instance.</p>
<blockquote>
<p>It’s an async operation, you can use promise or async/await functions.</p>
</blockquote>
<p>Once you are done with the connection, we will define our <code>Schema</code> and <code>Modal</code>.</p>
<p><strong><code>Schema</code> is required to let MongoDB know what kind of collections you are going to store into documents.</strong></p>
<pre><code class="language-js">// Create Schema for users
const usersSchema = new mongoose.Schema({
  age: Number,
  name: String,
  email: String
});

// Create Modal for users
const UsersModal = new mongoose.model('users', usersSchema);
</code></pre>
<blockquote>
<p>As I explained in my <a href="https://learnwithgurpreet.com/day-4-NodeJS">previous article</a>, <code>_id</code> will be autogenerated by MongoDB.</p>
</blockquote>
<p>Please refer to the following updated <code>app.js</code> file (reset of the project setup will remain the same):</p>
<pre><code class="language-js">require('dotenv').config();
const express = require('express');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');
const app = express();

// connect to the database
async function connectDB() {
  const {MONGO_USER, MONGO_HOST, MONGO_PASS, MONGO_DB} = process.env;
  await mongoose.connect(
    `mongodb+srv://${MONGO_USER}:${MONGO_PASS}@${MONGO_HOST}/${MONGO_DB}`,
    {
      useNewUrlParser: true,
      useUnifiedTopology: true,
      useFindAndModify: false,
      useCreateIndex: true
    }
  );
}

connectDB();

// Create Schema for users
const usersSchema = new mongoose.Schema({
  age: Number,
  name: String,
  email: String
});

// Create Modal for users
const UsersModal = new mongoose.model('users', usersSchema);

app.set('view engine', 'ejs');

app.use((req, res, next) =&gt; {
  res.append('Access-Control-Allow-Origin', ['*']);
  res.append('Access-Control-Allow-Methods', 'GET,PUT,POST,DELETE');
  res.append('Access-Control-Allow-Headers', 'Content-Type');
  if (req.url.includes('/api')) {
    res.append('Content-Type', 'text/json');
  }
  next();
});

// parse application/x-www-form-urlencoded
app.use(bodyParser.urlencoded({extended: false}));
app.use(bodyParser.json());
app.use('/assets', express.static('assets'));

const getUserInfo = id =&gt; {
  return USER_DATA.filter(obj =&gt; obj._id === id);
};

// Get list of users, and set data
app.get('/', (req, res) =&gt; {
  UsersModal.find({}, function (err, docs) {
    if (err) {
      res.status(500).send(err);
    }
    res.render('index', {
      data: docs
    });
  });
});

// Get single user by id, and set data
app.get('/user/:id', (req, res) =&gt; {
  UsersModal.findOne({_id: req.params.id}, function (err, doc) {
    if (err) {
      res.status(500).send(err);
    }
    res.render('user', {
      data: doc
    });
  });
});

// Loading view of contact page
app.get('/contact', (req, res) =&gt; {
  res.sendFile(`${__dirname}/contact.html`);
});

// RESTFul API Services

// get all users
app.get('/api/users', (req, res) =&gt; {
  UsersModal.find({}, function (err, docs) {
    if (err) {
      res.status(500).send(err);
    }
    res.send(docs);
  });
});

// get single user by id
app.get('/api/user/:id', (req, res) =&gt; {
  UsersModal.findOne({_id: req.params.id}, function (err, doc) {
    if (err) {
      res.status(500).send(err);
    }
    res.send(doc);
  });
});

// delete single user by id
app.delete('/api/user/:id', (req, res) =&gt; {
  UsersModal.findOneAndDelete({_id: req.params.id}, function (err, doc) {
    if (err) {
      res.status(500).send(err);
    }
    res.send(doc);
  });
});

// update single user by id
app.put('/api/user/:id', (req, res) =&gt; {
  const {name, age, email} = req.body;
  if (req.params.id) {
    UsersModal.updateOne({_id: req.params.id}, {name, age, email}, function (err, doc) {
      if (err) {
        res.status(500).send(err);
      }
      res.send(doc);
    });
  } else {
    res.status(500).send('id is missing in params');
  }
});

// add new user
app.post('/api/user', (req, res) =&gt; {
  const {name, age, email} = req.body;

  if (name &amp;&amp; age &amp;&amp; email) {
    UsersModal.create(
      {
        age,
        name,
        email
      },
      function (err, doc) {
        if (err) {
          res.status(500).send(err);
        }
        res.send(doc);
      }
    );
  } else {
    res.status(500).send('error, user not added.');
  }
});

app.listen(3000);
</code></pre>
